/* =========================
   COPY HELPERS
========================= */

function copy_planned_team_to_doc(frm, doctype, docname, callback) {
    let team = frm.doc.custom_planned_team || [];

    frappe.call({
        method: 'frappe.client.get',
        args: {
            doctype: doctype,
            name: docname
        },
        callback: function(r) {
            if (!r.message) {
                callback();
                return;
            }

            let target_doc = r.message;

            target_doc.custom_planned_team = [];

            team.forEach(row => {
                if (!row.custom_technician) return;

                target_doc.custom_planned_team.push({
                    doctype: 'Planned Technicians',
                    custom_technician: row.custom_technician
                });
            });

            frappe.call({
                method: 'frappe.client.save',
                args: {
                    doc: target_doc
                },
                callback: function() {
                    callback();
                }
            });
        }
    });
}

