function validate_request_ticket_type(frm) {
    if (!frm.doc.custom_request_type || !frm.doc.custom_ticket_type) {
        return true;
    }

    let allowed = TICKET_TYPE_BY_REQUEST_TYPE[frm.doc.custom_request_type] || ALL_TICKET_TYPES;

    if (!allowed.includes(frm.doc.custom_ticket_type)) {
        frappe.msgprint(
            __("Ticket Type {0} is not valid for Request Type {1}. Allowed: {2}", [
                frm.doc.custom_ticket_type,
                frm.doc.custom_request_type,
                allowed.join(", ")
            ])
        );
        return false;
    }

    return true;
}

function validate_ticket_ready(frm) {
    if (!validate_request_ticket_type(frm)) {
        return false;
    }

    if (!frm.doc.custom_customer || !frm.doc.custom_client_branch || !frm.doc.custom_target_equipment) {
        frappe.msgprint(__('Please select Customer, Client Branch, and Target Equipment first.'));
        return false;
    }

    if (!frm.doc.custom_planned_team || !frm.doc.custom_planned_team.length) {
        frappe.msgprint(__('Please assign at least one technician in Planned Team before continuing.'));
        return false;
    }

    return true;
}

function build_request_description(frm) {
    let parts = [];

    if (frm.doc.custom_subject) {
        parts.push('Subject: ' + frm.doc.custom_subject);
    }

    if (frm.doc.custom_request_type) {
        parts.push('Request Type: ' + frm.doc.custom_request_type);
    }

    if (frm.doc.custom_ticket_type) {
        parts.push('Ticket Type: ' + frm.doc.custom_ticket_type);
    }

    if (frm.doc.custom_component_group || frm.doc.custom_component_item) {
        parts.push(
            'Component: ' +
            [
                frm.doc.custom_component_group,
                frm.doc.custom_component_item,
                frm.doc.custom_component_serial ? 'SN: ' + frm.doc.custom_component_serial : ''
            ].filter(Boolean).join(' - ')
        );
    }

    if (frm.doc.custom_description) {
        parts.push('Description:\n' + frm.doc.custom_description);
    }

    return parts.join('\n\n');
}

