function find_active_contract(frm) {
    if (!frm.doc.custom_customer) return;

    frappe.call({
        method: 'frappe.client.get_list',
        args: {
            doctype: 'Maintenance Contract',
            filters: {
                custom_customer: frm.doc.custom_customer,
                custom_status: 'Active'
            },
            fields: [
                'name',
                'custom_contract_type',
                'custom_default_sla_rule',
                'custom_start_date',
                'custom_end_date'
            ]
        },
        callback: function(r) {
            let contracts = r.message || [];
            let today = frappe.datetime.get_today();

            contracts = contracts.filter(c =>
                (!c.custom_start_date || c.custom_start_date <= today) &&
                (!c.custom_end_date || c.custom_end_date >= today)
            );

            if (!contracts.length) return;

            let contract = contracts[0];

            frm.set_value('custom_maintenance_contract', contract.name);

            if (contract.custom_default_sla_rule) {
                frm.set_value('custom_sla_rule', contract.custom_default_sla_rule);
            }

            frm.set_value(
                'custom_service_type',
                contract.custom_contract_type === 'Warranty'
                    ? 'Warranty'
                    : contract.custom_contract_type === 'AMC'
                        ? 'AMC'
                        : 'Billable'
            );
        }
    });
}

