function load_equipment_warranty_status(frm) {
    if (!frm.doc.custom_target_equipment) {
        // Clear warranty display if no equipment
        frm.dashboard.clear_headline();
        return;
    }

    frappe.call({
        method: 'maintenance_app.api.get_equipment_warranty_status',
        args: {
            equipment_name: frm.doc.custom_target_equipment
        },
        callback: function(r) {
            if (!r.message) {
                return;
            }

            let warranty_info = r.message;

            // Show warranty status in dashboard header
            if (warranty_info.is_covered) {
                let indicator_color = warranty_info.days_remaining > 30 ? 'green' : 'orange';

                frm.dashboard.set_headline(
                    `<span style="font-size: 13px;"><b>WARRANTY:</b> ${warranty_info.coverage_type} - Expires in ${warranty_info.days_remaining} days (${warranty_info.warranty_end_date})</span>`,
                    indicator_color
                );

                // Also auto-link the warranty if there's a warranty field
                if (frm.fields_dict.custom_warranty) {
                    frm.set_value('custom_warranty', warranty_info.warranty_name);
                }

                // Show green alert
                frappe.show_alert({
                    message: warranty_info.message,
                    indicator: 'green'
                });
            } else {
                frm.dashboard.set_headline(
                    '<span style="font-size: 13px;"><b>WARRANTY:</b> No active warranty coverage</span>',
                    'red'
                );

                frappe.show_alert({
                    message: '⚠ Equipment has no active warranty',
                    indicator: 'orange'
                });
            }
        }
    });
}

function check_and_set_warranty_service_type(frm) {
    if (!frm.doc.custom_target_equipment) {
        return;
    }

    let equipment_name = frm.doc.custom_target_equipment;
    console.log('Checking warranty for equipment:', equipment_name);

    // Check for active warranty
    frappe.call({
        method: 'frappe.client.get_list',
        args: {
            doctype: 'Warranty',
            filters: {
                custom_installed_equipment: equipment_name,
                custom_warranty_status: 'Active'
            },
            fields: ['name', 'custom_warranty_end_date'],
            limit: 1
        },
        callback: function(r) {
            let warranties = r.message || [];

            if (warranties.length > 0) {
                // Active warranty found
                let warranty = warranties[0];
                console.log('Active warranty found:', warranty.name);

                frm.set_value('custom_service_type', 'Warranty');

                frappe.show_alert({
                    message: `✓ Equipment under Warranty - Service type set to Warranty`,
                    indicator: 'green'
                });

                return;
            }

            // No warranty, check for active maintenance contract
            console.log('No warranty found, checking for maintenance contract');
            find_active_contract(frm);
        }
    });
}

