function fetch_item_details(frm) {
    if (!frm.doc.custom_item_code) return;

    frappe.db.get_value(
        'Item',
        frm.doc.custom_item_code,
        ['item_name', 'brand', 'item_group'],
        function(r) {
            if (!r) return;

            if (r.brand) frm.set_value('custom_make', r.brand);
            if (r.item_name) frm.set_value('custom_model', r.item_name);
            if (r.item_group) frm.set_value('custom_asset_category', r.item_group);

            if (!frm.doc.custom_asset_name && r.item_name) {
                frm.set_value('custom_asset_name', r.item_name);
            }

            update_display_name(frm);
            set_installed_component_filters(frm);
        }
    );
}

function update_display_name(frm) {
    let equipment_name = frm.doc.custom_asset_name || '';
    let client_asset_code = frm.doc.custom_client_asset_code || '';
    let serial_number = frm.doc.custom_asset_id || '';

    let display_name = [equipment_name, client_asset_code, serial_number]
        .filter(Boolean)
        .join(' - ');

    if (
        frm.fields_dict.custom_display_name &&
        frm.doc.custom_display_name !== display_name
    ) {
        frm.set_value('custom_display_name', display_name);
    }
}

function set_branch_filter(frm) {
    frm.set_query('custom_branch', function() {
        if (!frm.doc.custom_parent_customer) return {};

        return {
            filters: [
                ['Client Branch', 'custom_parent_customer', '=', frm.doc.custom_parent_customer]
            ]
        };
    });
}

function sync_customer_from_branch(frm) {
    if (frm.doc.custom_branch && !frm.doc.custom_parent_customer) {
        frappe.db.get_value(
            'Client Branch',
            frm.doc.custom_branch,
            'custom_parent_customer',
            function(r) {
                if (r && r.custom_parent_customer) {
                    frm.set_value('custom_parent_customer', r.custom_parent_customer);
                }
            }
        );
    }
}

function validate_branch_customer(frm) {
    if (frm.doc.custom_parent_customer && frm.doc.custom_branch) {
        frappe.db.get_value(
            'Client Branch',
            frm.doc.custom_branch,
            'custom_parent_customer',
            function(r) {
                if (r && r.custom_parent_customer !== frm.doc.custom_parent_customer) {
                    frm.set_value('custom_branch', '');
                    frappe.msgprint(__('Selected branch does not belong to this customer.'));
                }
            }
        );
    }
}

function lock_core_fields(frm) {
    [
        'custom_asset_status',
        'custom_asset_type',
        'custom_asset_category',
        'custom_ownership'
    ].forEach(function(fieldname) {
        if (frm.fields_dict[fieldname]) {
            frm.set_df_property(fieldname, 'read_only', 1);
        }
    });
}

function populate_warranty_details(frm) {
    console.log('populate_warranty_details called');

    if (!frm.doc.custom_warranty) {
        console.log('No warranty selected');
        return;
    }

    let warranty_name = frm.doc.custom_warranty;
    console.log('Fetching warranty:', warranty_name);

    frappe.call({
        method: 'frappe.client.get',
        args: {
            doctype: 'Warranty',
            name: warranty_name
        },
        callback: function(r) {
            console.log('API Response:', r);

            if (!r.message) {
                console.log('Warranty not found or error fetching');
                frappe.msgprint('Could not fetch warranty details');
                return;
            }

            let warranty = r.message;
            console.log('Warranty object:', warranty);
            console.log('Period field value:', warranty.custom_warranty_period_years);
            console.log('Coverage field value:', warranty.custom_coverage_type);

            if (warranty.custom_warranty_period_years) {
                console.log('Setting period to:', warranty.custom_warranty_period_years);
                frm.set_value('custom_warranty_period_years', warranty.custom_warranty_period_years);
            } else {
                console.log('Period is empty');
            }

            if (warranty.custom_coverage_type) {
                console.log('Setting coverage to:', warranty.custom_coverage_type);
                frm.set_value('custom_coverage_type', warranty.custom_coverage_type);
            } else {
                console.log('Coverage type is empty');
            }

            if (warranty.custom_warranty_title) {
                frappe.show_alert({
                    message: `✓ Warranty linked: ${warranty.custom_warranty_title}`,
                    indicator: 'green'
                });
            }
        },
        error: function(err) {
            console.log('Error fetching warranty:', err);
            frappe.msgprint('Error fetching warranty details: ' + err.message);
        }
    });
}

