function display_combined_ie_status_banner(frm) {
    if (frm.is_new() || !frm.doc.name) {
        return;
    }

    console.log('display_combined_ie_status_banner called for:', frm.doc.name);

    frappe.call({
        method: 'frappe.client.get_list',
        args: {
            doctype: 'Warranty',
            filters: {
                custom_installed_equipment: frm.doc.name,
                custom_warranty_status: 'Active'
            },
            fields: [
                'name',
                'custom_warranty_title',
                'custom_warranty_end_date',
                'custom_coverage_type'
            ],
            order_by: 'custom_warranty_end_date asc',
            limit_page_length: 0
        },
        callback: function(r) {
            console.log('Warranty API response:', r.message);

            let warranties = r.message || [];
            let warranty_html = '';
            let banner_color = 'blue';

            if (warranties.length > 0) {
                let today = frappe.datetime.get_today();
                console.log('Today:', today);

                let active_warranties = warranties.filter(w => {
                    console.log('Checking warranty:', w.name, 'End date:', w.custom_warranty_end_date);
                    return w.custom_warranty_end_date && w.custom_warranty_end_date >= today;
                });

                console.log('Active warranties count:', active_warranties.length);

                if (active_warranties.length > 0) {
                    let earliest = active_warranties[0];

                    let end_parts = earliest.custom_warranty_end_date.split('-');
                    let today_parts = today.split('-');

                    let end_date = new Date(end_parts[0], end_parts[1] - 1, end_parts[2]);
                    let today_date = new Date(today_parts[0], today_parts[1] - 1, today_parts[2]);

                    let days_remaining = Math.ceil((end_date - today_date) / (1000 * 60 * 60 * 24));

                    console.log('Days remaining:', days_remaining);

                    if (days_remaining < 7) {
                        banner_color = 'red';
                    } else if (days_remaining < 30) {
                        banner_color = 'orange';
                    } else {
                        banner_color = 'green';
                    }

                    let warranty_count = active_warranties.length;
                    let count_text = warranty_count > 1 ? `${warranty_count} active warranties` : '1 active warranty';

                    warranty_html = `
                        <span style="color: inherit; font-weight: bold;">WARRANTY:</span> 
                        ${count_text} - ${earliest.custom_coverage_type} - 
                        Expires in ${days_remaining} days (${earliest.custom_warranty_end_date})
                    `;
                } else {
                    banner_color = 'red';
                    warranty_html = '<span style="color: inherit; font-weight: bold;">WARRANTY:</span> All warranties expired';
                }
            } else {
                warranty_html = '<span style="color: inherit; font-weight: bold;">WARRANTY:</span> No active warranty';
            }

            let headline = `
                <div style="line-height: 1.6;">
                    <div>
                        <span style="color: inherit; font-weight: bold;">OPERATIONAL:</span> 
                        Fields locked. Use interventions for operational changes.
                    </div>
                    <div style="margin-top: 8px; border-top: 1px solid rgba(0,0,0,0.1); padding-top: 8px;">
                        ${warranty_html}
                    </div>
                </div>
            `;

            console.log('Setting headline with color:', banner_color);
            frm.dashboard.set_headline(headline, banner_color);
        },
        error: function(err) {
            console.log('Error fetching warranties:', err);
        }
    });
}

/* ═══════════════════════════════════════════════════════════
   NEXT MAINTENANCE DATE CALCULATION
═══════════════════════════════════════════════════════════ */

function calculate_next_maintenance_date(frm) {
    if (!frm.doc.custom_last_service_date || !frm.doc.custom_maint_frequency) {
        return;
    }

    let last_service = moment(frm.doc.custom_last_service_date);
    let next_date;

    switch(frm.doc.custom_maint_frequency) {
        case 'Monthly':
            next_date = last_service.add(1, 'month').format('YYYY-MM-DD');
            break;
        case 'Quarterly':
            next_date = last_service.add(3, 'months').format('YYYY-MM-DD');
            break;
        case 'Bi-Annual':
            next_date = last_service.add(6, 'months').format('YYYY-MM-DD');
            break;
        case 'Annual':
            next_date = last_service.add(1, 'year').format('YYYY-MM-DD');
            break;
        default:
            next_date = null;
    }

    if (next_date) {
        frm.set_value('custom_next_maintenance', next_date);

        let today = moment();
        let due_date = moment(next_date);
        let days_until = due_date.diff(today, 'days');

        if (days_until <= 0) {
            frappe.show_alert({
                message: __('⚠️ Maintenance is overdue by ' + Math.abs(days_until) + ' days'),
                indicator: 'orange'
            });
        } else if (days_until <= 7) {
            frappe.show_alert({
                message: __('⏰ Maintenance due in ' + days_until + ' days'),
                indicator: 'yellow'
            });
        }
    } else {
        frm.set_value('custom_next_maintenance', null);
    }
}

