function add_mission_buttons(frm) {
    frm.clear_custom_buttons();

    if (frm.is_new()) return;

    if (['Closed', 'Cancelled'].includes(frm.doc.custom_mission_status)) {
        return;
    }

    frappe.call({
        method: 'frappe.client.get_list',
        args: {
            doctype: 'Mission Intervention',
            filters: {
                custom_parent_mission: frm.doc.name
            },
            fields: ['name', 'docstatus'],
            limit_page_length: 50
        },
        callback: function(r) {
            let interventions = r.message || [];
            let has_any_mi = interventions.length > 0;
            let open_mi = null;

            interventions.forEach(function(row) {
                if (row.docstatus === 0 && !open_mi) {
                    open_mi = row.name;
                }
            });

            if (has_any_mi) {
                frm.add_custom_button(__('Add Additional MI'), function() {
                    create_additional_mi(frm);
                }, __('Actions'));
            }

            if (frm.doc.custom_mission_status !== 'Completed') {
                if (open_mi) {
                    frm.add_custom_button(__('Open Current Intervention'), function() {
                        frappe.set_route('Form', 'Mission Intervention', open_mi);
                    }, __('Actions'));
                } else {
                    frm.add_custom_button(__('Create Intervention'), function() {
                        create_intervention(frm);
                    }, __('Actions'));
                }
            }
        }
    });
}

function create_intervention(frm) {
    frappe.call({
        method: 'maintenance_app.api.create_intervention_from_mission',
        args: {
            mission_name: frm.doc.name
        },
        freeze: true,
        freeze_message: __('Creating Intervention...'),
        callback: function(r) {
            if (!r.message) {
                return;
            }

            frm.reload_doc().then(function() {
                frappe.set_route(
                    'Form',
                    'Mission Intervention',
                    r.message.intervention
                );
            });
        }
    });
}

function create_additional_mi(frm) {
    frappe.prompt([
        {
            label: __('Equipment'),
            fieldname: 'asset',
            fieldtype: 'Link',
            options: 'Installed Equipment',
            reqd: 1,
            get_query: function() {
                return {
                    filters: {
                        custom_parent_customer: frm.doc.custom_parent_customer,
                        custom_branch: frm.doc.custom_branch
                    }
                };
            }
        },
        {
            label: __('Reason'),
            fieldname: 'reason',
            fieldtype: 'Small Text',
            reqd: 1
        }
    ],
    function(values) {
        frappe.call({
            method: 'maintenance_app.api.create_additional_intervention_from_mission',
            args: {
                mission_name: frm.doc.name,
                asset_name: values.asset,
                reason: values.reason
            },
            freeze: true,
            freeze_message: __('Creating Additional Intervention...'),
            callback: function(r) {
                if (!r.message) {
                    return;
                }

                frm.reload_doc().then(function() {
                    frappe.set_route(
                        'Form',
                        'Mission Intervention',
                        r.message.intervention
                    );
                });
            }
        });
    },
    __('Additional Equipment Found'),
    __('Create MI'));
}

