frappe.ui.form.on('Mission Intervention Item', {
    custom_item_code: function(frm, cdt, cdn) {
        let row = locals[cdt][cdn];

        if (!row.custom_item_code) return;

        frappe.db.get_value(
            'Item',
            row.custom_item_code,
            ['item_name', 'brand', 'is_stock_item'],
            function(r) {
                if (!r) return;

                if (!r.is_stock_item) {
                    frappe.model.set_value(cdt, cdn, 'custom_item_code', '');
                    frappe.throw(__('Only stock items are allowed in the parts table.'));
                }

