/* =========================
   LIFECYCLE CLASSIFICATION OPTIONS
========================= */

const LIFECYCLE_OPTIONS_BY_INTERVENTION_TYPE = {
    "Asset Relocation": ["Relocated"],
    "Swap": ["Permanent Swap", "Client Replacement"],
    "Loan": ["Loan Issued", "Loan Returned"],
    "Repair": ["Sent For Repair", "Returned From Repair"],
    "Installation": ["Installed"],
    "Commissioning": ["Commissioned"],
    "Retirement": ["Retired"],
    "Disposal": ["Disposed"]
};

function apply_lifecycle_classification_options(frm) {
    if (!frm.fields_dict.custom_swap_classification) {
        return;
    }

    let type = frm.doc.custom_intervention_type || "";
    let options = LIFECYCLE_OPTIONS_BY_INTERVENTION_TYPE[type] || [];

    if (!options.length) {
        frm.set_df_property("custom_swap_classification", "options", "\n");
        frm.set_value("custom_swap_classification", "");
        frm.refresh_field("custom_swap_classification");
        return;
    }

    frm.set_df_property("custom_swap_classification", "options", "\n" + options.join("\n"));
    frm.refresh_field("custom_swap_classification");

    if (options.length === 1) {
        if (frm.doc.custom_swap_classification !== options[0]) {
            frm.set_value("custom_swap_classification", options[0]);
        }
        return;
    }

    if (
        frm.doc.custom_swap_classification &&
        !options.includes(frm.doc.custom_swap_classification)
    ) {
        frm.set_value("custom_swap_classification", "");
    }
}

function toggle_intervention_fields(frm) {
    let type = frm.doc.custom_intervention_type || "";
    let checked_in = !!frm.doc.custom_start_time;

    apply_lifecycle_classification_options(frm);

    let asset_change_fields = [
        "custom_new_branch",
        "custom_swap_classification",
        "custom_removed_asset_outcome",
        "custom_new_make",
        "custom_new_model",
        "custom_new_serial",
        "custom_new_asset",
        "custom_loan_required",
        "custom_loan_approved",
        "custom_loan_return",
        "custom_asset_change_reason"
    ];

    asset_change_fields.forEach(function(fieldname) {
        if (frm.fields_dict[fieldname]) {
            frm.set_df_property(fieldname, "hidden", 1);
            frm.set_df_property(fieldname, "reqd", 0);
        }
    });

    function show_fields(fields) {
        fields.forEach(function(fieldname) {
            if (frm.fields_dict[fieldname]) {
                frm.set_df_property(fieldname, "hidden", 0);
                frm.set_df_property(fieldname, "reqd", 0);
            }
        });
    }

    function clear_fields(fields) {
        fields.forEach(function(fieldname) {
            if (frm.fields_dict[fieldname] && frm.doc[fieldname]) {
                frm.set_value(fieldname, "");
            }
        });
    }

    // Movement fields must not block Check In.
    // Before Submit server script validates required movement fields.
    if (!checked_in) {
        return;
    }

    if (type === "Asset Relocation") {
        show_fields([
            "custom_swap_classification",
            "custom_new_branch",
            "custom_asset_change_reason"
