        clear_fields([
            "custom_removed_asset_outcome",
            "custom_new_asset",
            "custom_new_serial",
            "custom_new_make",
            "custom_new_model",
            "custom_loan_required",
            "custom_loan_approved",
            "custom_loan_return"
