            "custom_loan_required",
            "custom_loan_approved",
            "custom_loan_return",
            "custom_asset_change_reason",
            "custom_removed_asset_outcome"
        ]);
    }

    if (type === "Repair") {
        show_fields([
            "custom_swap_classification",
            "custom_new_branch",
            "custom_asset_change_reason",
            "custom_removed_asset_outcome"
        ]);

        clear_fields([
            "custom_new_asset",
            "custom_new_serial",
            "custom_new_make",
            "custom_new_model",
            "custom_loan_required",
            "custom_loan_approved",
            "custom_loan_return"
        ]);
    }

    if (type === "Installation") {
        show_fields([
            "custom_swap_classification",
            "custom_new_branch",
            "custom_asset_change_reason"
        ]);

        clear_fields([
            "custom_removed_asset_outcome",
            "custom_new_asset",
            "custom_new_serial",
            "custom_new_make",
            "custom_new_model",
            "custom_loan_required",
            "custom_loan_approved",
            "custom_loan_return"
        ]);
    }

    if (type === "Commissioning") {
        show_fields([
            "custom_swap_classification",
            "custom_new_branch",
            "custom_asset_change_reason"
        ]);

        clear_fields([
            "custom_removed_asset_outcome",
            "custom_new_asset",
            "custom_new_serial",
            "custom_new_make",
            "custom_new_model",
            "custom_loan_required",
            "custom_loan_approved",
            "custom_loan_return"
        ]);
    }

    if (type === "Retirement") {
        show_fields([
            "custom_swap_classification",
            "custom_removed_asset_outcome",
            "custom_asset_change_reason"
        ]);

        clear_fields([
            "custom_new_branch",
            "custom_new_asset",
            "custom_new_serial",
            "custom_new_make",
            "custom_new_model",
            "custom_loan_required",
            "custom_loan_approved",
            "custom_loan_return"
        ]);
    }

    if (type === "Disposal") {
        show_fields([
