========================= */

function calculate_hours(frm) {
    if (!frm.doc.custom_start_time || !frm.doc.custom_end_time) return;

    let start = moment(frm.doc.custom_start_time);
    let end = moment(frm.doc.custom_end_time);
    let diff = end.diff(start, 'minutes');

    if (diff <= 0) return;

    frm.set_value('custom_hours_worked', flt(diff / 60, 2));
}

function set_config_datetime(cdt, cdn) {
    let row = locals[cdt][cdn];

    if (!row.custom_config_datetime) {
        frappe.model.set_value(
            cdt,
            cdn,
            'custom_config_datetime',
            frappe.datetime.now_datetime()
        );
    }
}

function validate_before_submit(frm) {
    if (!frm.doc.custom_start_time) {
        frappe.throw(__('Please Check In before submitting.'));
    }

    if (!frm.doc.custom_completed_time) {
        frappe.throw(__('Please Complete Work before submitting.'));
    }

    if (!frm.doc.custom_work_outcome) {
        frappe.throw(__('Work Outcome is required.'));
    }

    if (!frm.doc.custom_work_progress) {
        frappe.throw(__('Technical Progress Notes are required.'));
    }

    if (!frm.doc.custom_client_signature_received) {
        frappe.throw(__('Please mark Client Signed before submitting.'));
    }

    if (!frm.doc.custom_client_signed_time) {
        frappe.throw(__('Client Signed Time is required.'));
    }

    if (!frm.doc.custom_end_time) {
        frappe.throw(__('Please Check Out before submitting.'));
    }

    /*frm.set_value('custom_checkout_status', 'Submitted');*/
}

function lock_ratings_if_confirmed(frm) {
    if (frm.doc.custom_quality_score && frm.doc.custom_hse_score) {
        frm.set_df_property('custom_quality_score', 'read_only', 1);
        frm.set_df_property('custom_hse_score', 'read_only', 1);
    }
}

function confirm_and_lock_ratings(frm) {
    if (
        frm.doc.custom_quality_score &&
        frm.doc.custom_hse_score &&
        !frm.doc.__ratings_confirmed
    ) {
        frappe.confirm(__('Confirm ratings? They will be locked.'), function() {
            frm.doc.__ratings_confirmed = true;
            frm.set_df_property('custom_quality_score', 'read_only', 1);
            frm.set_df_property('custom_hse_score', 'read_only', 1);
        });
    }
}

