function fetch_ticket_from_invoice(frm) {

    if (frm.doc.custom_service_ticket) {
        return;
    }

    let references = frm.doc.references || [];

    let invoice_row = references.find(row =>
        row.reference_doctype === 'Sales Invoice' &&
        row.reference_name
    );

    if (!invoice_row) {
        return;
    }

    frappe.db.get_value(
        'Sales Invoice',
        invoice_row.reference_name,
        'custom_service_ticket'
    ).then(r => {

        if (r.message && r.message.custom_service_ticket) {

            frm.set_value(
                'custom_service_ticket',
                r.message.custom_service_ticket
            );
        }
    });
}

