    setup: function(frm) {

        frm.set_query('custom_client_branch', function() {

            let customer = '';

            if (
                frm.doc.links &&
                frm.doc.links.length > 0
            ) {

                let customer_link = frm.doc.links.find(function(l) {

                    return l.link_doctype === 'Customer';

                });

                if (customer_link) {
                    customer = customer_link.link_name;
