            }

            return {
                filters: {
                    custom_parent_customer: customer
                }
            };
        });
    }
});

function toggle_branch_field(frm) {

    if (frm.doc.custom_contact_scope === 'Branch Level') {

        frm.set_df_property(
            'custom_client_branch',
            'hidden',
            0
        );

        frm.set_df_property(
            'custom_client_branch',
            'reqd',
            1
        );
    }
    else {

        frm.set_value('custom_client_branch', '');

        frm.set_df_property(
            'custom_client_branch',
            'hidden',
            1
        );

        frm.set_df_property(
            'custom_client_branch',
            'reqd',
            0
        );
    }
}

/**
 * Warranty DocType - Client Script
 * - Auto-calculates warranty end date from start date + period (years)
 * - Filters branch by customer
 * - Filters equipment by customer + branch
 */

frappe.ui.form.on('Warranty', {

    // When start date changes, recalculate end date
    custom_warranty_start_date: function(frm) {
        calculate_warranty_end_date(frm);
    },

    // When period changes, recalculate end date
    custom_warranty_period_years: function(frm) {
        calculate_warranty_end_date(frm);
    },

    // When customer changes, reset branch and equipment
    custom_customer: function(frm) {
        frm.set_value('custom_branch', '');
        frm.set_value('custom_installed_equipment', '');
        set_warranty_filters(frm);
    },

    // When branch changes, reset equipment
    custom_branch: function(frm) {
        frm.set_value('custom_installed_equipment', '');
        set_warranty_filters(frm);
    },

    // On form load, ensure end date is calculated and filters are set
    onload: function(frm) {
        calculate_warranty_end_date(frm);
        set_warranty_filters(frm);
    },

    // On form refresh, ensure end date is calculated and filters are set
    refresh: function(frm) {
        calculate_warranty_end_date(frm);
        set_warranty_filters(frm);
    }
});

/**
 * Set query filters for branch and equipment fields
 */
function set_warranty_filters(frm) {
    // Filter Branch by Customer
    if (frm.fields_dict.custom_branch) {
        frm.set_query('custom_branch', () => ({
            filters: [
                ['Client Branch', 'custom_parent_customer', '=', frm.doc.custom_customer || '']
            ]
        }));
    }

    // Filter Equipment by Customer AND Branch
    if (frm.fields_dict.custom_installed_equipment) {
        frm.set_query('custom_installed_equipment', () => ({
            filters: [
                ['Installed Equipment', 'custom_parent_customer', '=', frm.doc.custom_customer || ''],
                ['Installed Equipment', 'custom_branch', '=', frm.doc.custom_branch || '']
            ]
        }));
    }
}

/**
 * Calculate warranty end date
 * Formula: end_date = start_date + (period_years * 365 days)
 */
function calculate_warranty_end_date(frm) {

    // Get start date and period
    const start_date = frm.doc.custom_warranty_start_date;
    const period_years = frm.doc.custom_warranty_period_years;

    // Both fields must have values
    if (!start_date || !period_years) {
        frm.set_value('custom_warranty_end_date', null);
        return;
    }

    // Calculate end date
    const start = frappe.datetime.str_to_obj(start_date);
    const days_to_add = period_years * 365;

    // Add days to start date
    start.setDate(start.getDate() + days_to_add);

    // Format as YYYY-MM-DD
    const end_date = frappe.datetime.obj_to_str(start).split(' ')[0];

    // Set the end date field
    frm.set_value('custom_warranty_end_date', end_date);

    // Show info message
    frappe.show_alert({
        message: `Warranty end date calculated: ${end_date}`,
        indicator: 'green'
    });
}
